package org.opensourcepingpong.membership;
import jakarta.validation.Valid; import org.opensourcepingpong.auth.AuthPrincipal; import org.opensourcepingpong.common.api.ApiResponse; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class MembershipController {private final MembershipService service;private final MemberQrService qr;public MembershipController(MembershipService s,MemberQrService q){service=s;qr=q;} @PostMapping("/membership/applications") ApiResponse<MembershipService.ApplicationView> apply(@AuthenticationPrincipal AuthPrincipal p,@Valid @RequestBody MembershipService.ApplyRequest r){return ApiResponse.ok(service.apply(p.userId(),r));} @GetMapping("/membership/applications/me") ApiResponse<MembershipService.ApplicationView> mine(@AuthenticationPrincipal AuthPrincipal p){return ApiResponse.ok(service.mine(p.userId()));} @PostMapping("/membership/me/qr") ApiResponse<MemberQrService.QrToken> qr(@AuthenticationPrincipal AuthPrincipal p){return ApiResponse.ok(qr.generate(p.userId()));} @GetMapping("/public/member-verifications/{token}") ApiResponse<MemberQrService.Verification> verify(@PathVariable String token){return ApiResponse.ok(qr.verify(token));} @GetMapping("/admin/membership/applications") ApiResponse<?> pending(@AuthenticationPrincipal AuthPrincipal p){return ApiResponse.ok(service.pending(p.userId()));} @PostMapping("/admin/membership/applications/{id}/approve") ApiResponse<Void> approve(@AuthenticationPrincipal AuthPrincipal p,@PathVariable java.util.UUID id,@RequestBody(required=false) java.util.Map<String,String> r){service.review(p.userId(),id,true,r==null?null:r.get("comment"));return ApiResponse.ok(null);} @PostMapping("/admin/membership/applications/{id}/reject") ApiResponse<Void> reject(@AuthenticationPrincipal AuthPrincipal p,@PathVariable java.util.UUID id,@RequestBody(required=false) java.util.Map<String,String> r){service.review(p.userId(),id,false,r==null?null:r.get("comment"));return ApiResponse.ok(null);} }
